--------------------------------------------------------
--  DDL for Trigger MEDICONODISPONIBLE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "MEDICITA_DB_USR"."MEDICONODISPONIBLE" 
BEFORE INSERT ON MEDICITA_DB_USR.CITA
FOR EACH ROW
DECLARE
    v_id_horario            NUMBER;
    v_cupo_maximo           NUMBER;
    v_citas_agendadas       NUMBER;
    v_dia_semana_cita       NUMBER;
    v_hora_inicio_horario   TIMESTAMP;
    v_hora_fin_horario      TIMESTAMP;
BEGIN
    -- 1. Determinar el día de la semana de la cita
    v_dia_semana_cita := TO_NUMBER(TO_CHAR(:NEW.FECHA, 'D'));

    -- 2. Buscar el horario. 
    -- CORRECCION: Usamos las columnas D.HORA_INICIO/FIN en el WHERE, no las variables.
    BEGIN
        SELECT 
            H.ID_HORARIO,
            H.CUPO_MAXIMO,
            D.HORA_INICIO,
            D.HORA_FIN
        INTO 
            v_id_horario, 
            v_cupo_maximo,
            v_hora_inicio_horario,
            v_hora_fin_horario
        FROM 
            MEDICITA_DB_USR.DISPONIBILIDAD D
        JOIN 
            MEDICITA_DB_USR.HORARIO H ON D.ID_DISPONIBILIDAD = H.ID_DISPONIBILIDAD
        WHERE 
            D.ID_MEDICO = :NEW.ID_MEDICO 
            AND D.DIA_SEMANA = v_dia_semana_cita 
            AND H.FECHA = :NEW.FECHA
            -- AQUI ESTABA EL ERROR: Usar columnas D.* en lugar de variables v_*
            AND :NEW.HORA BETWEEN D.HORA_INICIO AND D.HORA_FIN
            AND ROWNUM = 1;

    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(-20001, 'El médico no tiene un horario de disponibilidad configurado para la fecha (' || TO_CHAR(:NEW.FECHA) || ') y hora solicitadas.');
            RETURN; 
    END;

    -- 3. Contar citas agendadas
    SELECT 
        COUNT(*)
    INTO 
        v_citas_agendadas
    FROM 
        MEDICITA_DB_USR.CITA C
    WHERE 
        C.ID_MEDICO = :NEW.ID_MEDICO
        -- Validamos contra el mismo rango de fecha/hora para ser precisos
        AND C.FECHA = :NEW.FECHA
        AND C.HORA BETWEEN v_hora_inicio_horario AND v_hora_fin_horario 
        AND C.ID_CITA != NVL(:NEW.ID_CITA, -1); 

    -- 4. Validar cupo
    IF v_citas_agendadas >= v_cupo_maximo THEN
        RAISE_APPLICATION_ERROR(-20002, 
            'El cupo del horario para el médico en la fecha ' || TO_CHAR(:NEW.FECHA, 'DD-MON-YYYY') || ' está lleno. Cupo Máximo: ' || v_cupo_maximo
        );
    END IF;

END;
/
ALTER TRIGGER "MEDICITA_DB_USR"."MEDICONODISPONIBLE" ENABLE;
--------------------------------------------------------
--  DDL for Trigger PACIENTECITADUPLICADA
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "MEDICITA_DB_USR"."PACIENTECITADUPLICADA" 
BEFORE INSERT ON MEDICITA_DB_USR.CITA
FOR EACH ROW
DECLARE
    -- Variable para almacenar si ya existe una cita con los mismos datos
    v_existe_cita NUMBER;

    -- Excepción personalizada
    e_cita_duplicada EXCEPTION;
    PRAGMA EXCEPTION_INIT(e_cita_duplicada, -20003);

BEGIN
    -- 1. Contar el número de citas que ya existen para este paciente en la misma FECHA y HORA
    SELECT COUNT(ID_CITA)
    INTO v_existe_cita
    FROM MEDICITA_DB_USR.CITA
    WHERE ID_PACIENTE = :NEW.ID_PACIENTE -- Mismo paciente
      AND FECHA = :NEW.FECHA             -- Misma fecha
      AND HORA = :NEW.HORA;              -- Misma hora

    -- 2. Validar el resultado de la cuenta
    IF v_existe_cita > 0 THEN
        -- Si ya existe una cita, se lanza un error y se detiene la inserción
        RAISE_APPLICATION_ERROR(-20003, 
            'Ya existe una cita agendada para el paciente [' || :NEW.ID_PACIENTE || '] en la fecha ' || TO_CHAR(:NEW.FECHA, 'DD-MON-YYYY') || ' y hora ' || TO_CHAR(:NEW.HORA, 'HH24:MI') || '.'
        );
    END IF;
END;

/
ALTER TRIGGER "MEDICITA_DB_USR"."PACIENTECITADUPLICADA" ENABLE;
