--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_ALERGIA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "MEDICITA_DB_USR"."SP_UPDATE_ALERGIA" (
    p_id_alergia IN NUMBER,
    p_nombre IN NVARCHAR2 DEFAULT NULL,
    p_descripcion IN NVARCHAR2 DEFAULT NULL
) AS
BEGIN
